"""Shared dependency-free searchable multi-select for standalone HTML reports."""

MULTI_STYLE = '''
.multi-field{display:flex;flex-direction:column;gap:8px;font-size:12px;color:#64788c;min-width:140px}
.search-multi{position:relative;min-width:140px;max-width:270px;color:#19354b;font-size:13px}
.search-multi>summary{list-style:none;cursor:pointer;border:1px solid #ccd9e4;border-radius:7px;background:white;padding:9px 28px 9px 10px;min-height:38px;font-weight:400;max-width:270px;white-space:normal}
.search-multi>summary:after{content:'▾';position:absolute;right:10px;top:10px}.search-multi>summary::-webkit-details-marker{display:none}
.multi-popover{position:absolute;top:100%;left:0;width:300px;max-width:calc(100vw - 40px);background:white;border:1px solid #cbd7e2;border-radius:10px;padding:12px;box-shadow:0 10px 30px #18355320;z-index:30}
.multi-popover input[type=search]{width:100%;padding:9px;border:1px solid #cbd7e2;border-radius:6px;font:inherit;min-height:36px}.multi-tools{display:flex;gap:8px;margin:9px 0}.multi-tools button{padding:5px 8px;font-size:12px;min-height:30px}.multi-list{max-height:235px;overflow:auto}
.multi-list label{display:flex!important;flex-direction:row!important;align-items:center;gap:8px!important;padding:7px 3px;cursor:pointer;font-size:13px!important;color:#19354b!important;min-width:0!important}.multi-list input[type=checkbox]{width:16px!important;height:16px;min-height:16px!important;flex:none}.multi-list label span{overflow-wrap:anywhere}
.multi-tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:5px;max-width:270px}.multi-tag{font-size:11px;padding:3px 6px;min-height:24px;max-width:100%;overflow-wrap:anywhere;background:#eaf3fb;border:1px solid #d2e3f0;border-radius:5px}.multi-empty{padding:10px;color:#64788c}
@media(max-width:600px){.search-multi,.search-multi>summary{max-width:100%;min-width:125px}.multi-popover{position:fixed;left:12px;right:12px;top:20vh;width:auto;max-width:none}.multi-list{max-height:40vh}}
@media print{.search-multi{display:none}}
'''

MULTI_SCRIPT = '''
function multiValues(id){return [...document.getElementById(id).selectedOptions].map(o=>o.value).filter(v=>v&&v!=='all')}
function multiSetValues(id,values){const select=document.getElementById(id),list=Array.isArray(values)?values:[values];for(const option of select.options)option.selected=list.includes(option.value);select.searchMulti?.refresh()}
class SearchMultiSelect{
 constructor(select,allLabel){this.select=select;this.allLabel=allLabel;this.sourceLabel=select.closest('label');if(this.sourceLabel){const container=document.createElement('div');container.className=this.sourceLabel.className+' multi-field';this.sourceLabel.replaceWith(container);container.append(...this.sourceLabel.childNodes);this.sourceLabel=container}this.select.multiple=true;this.select.hidden=true;for(const option of [...select.options])if(!option.value||option.value==='all')option.remove();this.root=document.createElement('details');this.root.className='search-multi';this.summary=document.createElement('summary');this.summary.setAttribute('aria-label',allLabel+' 복수 선택');this.root.append(this.summary);this.pop=document.createElement('div');this.pop.className='multi-popover';this.search=document.createElement('input');this.search.type='search';this.search.placeholder='검색';this.search.setAttribute('aria-label',allLabel+' 검색');this.pop.append(this.search);const tools=document.createElement('div');tools.className='multi-tools';for(const [label,handler] of [['검색 결과 선택',()=>this.chooseVisible()],['전체로 초기화',()=>this.clear()]]){const button=document.createElement('button');button.type='button';button.textContent=label;button.onclick=handler;tools.append(button)}this.pop.append(tools);this.list=document.createElement('div');this.list.className='multi-list';this.pop.append(this.list);this.root.append(this.pop);this.tags=document.createElement('div');this.tags.className='multi-tags';select.after(this.root,this.tags);select.searchMulti=this;this.search.oninput=()=>this.refreshList();select.addEventListener('change',()=>this.refresh());this.root.addEventListener('toggle',()=>{if(this.root.open){document.querySelectorAll('.search-multi').forEach(other=>{if(other!==this.root)other.open=false});this.search.focus()}});this.root.addEventListener('keydown',event=>{if(event.key==='Escape'){this.root.open=false;this.summary.focus()}});document.addEventListener('pointerdown',event=>{if(!this.root.contains(event.target))this.root.open=false});this.refresh()}
 changed(){this.select.dispatchEvent(new Event('change',{bubbles:true}))}
 clear(){for(const option of this.select.options)option.selected=false;this.changed()}
 chooseVisible(){const query=this.search.value.toLocaleLowerCase();for(const option of this.select.options)if(option.text.toLocaleLowerCase().includes(query))option.selected=true;this.changed()}
 refreshList(){const focused=this.list.contains(document.activeElement)?document.activeElement.getAttribute('aria-label'):null;const query=this.search.value.toLocaleLowerCase();this.list.replaceChildren();for(const option of this.select.options){if(!option.text.toLocaleLowerCase().includes(query))continue;const label=document.createElement('label'),check=document.createElement('input'),text=document.createElement('span');check.type='checkbox';check.checked=option.selected;check.setAttribute('aria-label',option.text);check.onchange=()=>{option.selected=check.checked;this.changed()};text.textContent=option.text;label.append(check,text);this.list.append(label)}if(!this.list.children.length){const empty=document.createElement('div');empty.className='multi-empty';empty.textContent='검색 결과가 없습니다.';this.list.append(empty)}if(focused){const target=[...this.list.querySelectorAll('input')].find(input=>input.getAttribute('aria-label')===focused);target?.focus({preventScroll:true})}}
 refresh(){const selected=[...this.select.selectedOptions];this.summary.textContent=selected.length?selected.length+'개 선택':this.allLabel;this.tags.replaceChildren();for(const option of selected){const button=document.createElement('button');button.type='button';button.className='multi-tag';button.textContent=option.text+' ×';button.setAttribute('aria-label',option.text+' 선택 해제');button.onclick=()=>{option.selected=false;this.changed()};this.tags.append(button)}this.refreshList()}
}
'''
